{
  "IP": "neorv32_twd",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "TWD controller enable",
      "Unit": "neorv32_twd",
      "Information": "The operational enable setting determines whether the two-wire engine, FIFO clearing, sampling, interrupt generation and clock-generation output are active. The controller's operation depends on this setting.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity: an unchecked bus write loads the enable bit at line 159, and the bit controls the engine and FIFO operation at lines 230, 281, 381 and 389. Availability: the enable can clear both FIFOs and prevent or terminate protocol activity at lines 230, 281, 381, 389, 397, 421, 434 and 465.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker issuing an unchecked control write could disable the controller, clear buffered data and prevent two-wire transfers.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data",
        "clkgen_en_o"
      ],
      "Entry Lines": [
        159
      ],
      "Held Lines": [
        138,
        159
      ],
      "Exit Lines": [
        172,
        198
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Two-wire device address",
      "Unit": "neorv32_twd",
      "Information": "The stored seven-bit device address identifies which two-wire transactions this controller accepts. Protocol behavior depends on matching the received address against this setting.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity: an unchecked bus write changes the stored address at line 163, and the comparison at line 402 selects the protocol state. Availability: a wrong address prevents the controller from entering the response state at lines 401 through 408.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could rewrite the address so that the controller responds to unintended transactions or ignores all intended ones.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        163
      ],
      "Held Lines": [
        142,
        163
      ],
      "Exit Lines": [
        174
      ]
    },
    {
      "Concept ID": "C3",
      "Concept Name": "Transmit underrun data policy",
      "Unit": "neorv32_twd",
      "Information": "The transmit dummy-enable setting selects whether a saved byte is used when the transmit FIFO has no available byte. Read-transfer behavior depends on this fallback policy.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity: an unchecked bus write changes the setting at line 167, and line 251 selects between FIFO data, the saved byte and an all-ones value that is later transmitted at lines 429 and 464.",
      "Objectives At Risk": [
        "I"
      ],
      "Attack": "An attacker could change the fallback policy so that an empty transmit FIFO produces an incorrect byte on the two-wire interface.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        167
      ],
      "Held Lines": [
        146,
        167
      ],
      "Exit Lines": [
        178
      ]
    },
    {
      "Concept ID": "C4",
      "Concept Name": "Read suppression policy",
      "Unit": "neorv32_twd",
      "Information": "The hide-read setting determines whether a read request is suppressed when the transmit FIFO is full. The setting controls whether a read transaction is allowed to proceed.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity: an unchecked bus write changes the policy at line 168, and the condition at line 403 changes the selected engine state. Availability: the same condition can force the engine to remain out of the response path at lines 403 through 406.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could alter the policy to expose unintended reads or suppress legitimate read transfers whenever the transmit FIFO is full.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        168
      ],
      "Held Lines": [
        147,
        168
      ],
      "Exit Lines": [
        179
      ]
    },
    {
      "Concept ID": "C5",
      "Concept Name": "Transmitted two-wire data",
      "Unit": "neorv32_twd",
      "Information": "This is the byte data supplied through the processor bus and sent to the two-wire peer during read transfers. The controller depends on preserving and transmitting these bytes correctly.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality: bus data enters the transmit path at line 232 and is exposed on the two-wire output through the assignment at line 454. Integrity: the transmit byte is accepted from the bus, saved for fallback at line 242 and shifted to the output, so corruption or replacement changes the peer-visible data. Availability: controller disable or FIFO clearing at lines 230 and 369 can discard or withhold the transmit data, while the full-FIFO condition at lines 403 through 406 can suppress a read transfer.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker could observe the two-wire output, overwrite the queued byte, or disable and clear the transmit path so the peer receives secret or incorrect data or no data.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "twd_sda_o"
      ],
      "Entry Lines": [
        232
      ],
      "Held Lines": [
        242
      ],
      "Exit Lines": [
        454
      ]
    },
    {
      "Concept ID": "C6",
      "Concept Name": "Received two-wire data",
      "Unit": "neorv32_twd",
      "Information": "This is byte data received from the two-wire SDA input and returned to software through the bus response. The controller depends on sampling, buffering and returning the received bytes correctly.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality: sampled SDA data enters at line 311 and is exposed to the bus response at line 190. Integrity: the sampled bits are shifted into the engine and written toward the receive FIFO at lines 412, 449 and 282, so alteration in this path changes the returned byte. Availability: receive FIFO clearing and full-buffer handling at lines 281 and 439 can discard or stop accepting received data.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker could spoof the SDA input or clear or block the receive path so software receives exposed, corrupted or missing data.",
      "Enters Through": [
        "twd_sda_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        311
      ],
      "Held Lines": [],
      "Exit Lines": [
        190
      ]
    },
    {
      "Concept ID": "C7",
      "Concept Name": "Interrupt request",
      "Unit": "neorv32_twd",
      "Information": "The interrupt request reports configured receive and transmit FIFO conditions to the integrating system. Software service of the controller can depend on this notification.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity: the interrupt output is produced by the condition at lines 293 through 296, so changes to the enable and FIFO-condition inputs can generate a false interrupt. Availability: suppressing that assignment's true condition can withhold notification needed to service FIFO transfers.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could manipulate the controller configuration or FIFO conditions to suppress required interrupts or cause spurious service requests.",
      "Enters Through": [],
      "Leaves Through": [
        "irq_o"
      ],
      "Entry Lines": [],
      "Held Lines": [
        293
      ],
      "Exit Lines": [
        293
      ]
    },
    {
      "Concept ID": "C8",
      "Concept Name": "Sampled SDA line state",
      "Unit": "neorv32_twd",
      "Information": "The sampled SDA line level is protocol-observation state used to detect two-wire events and is also returned as a readable status value. Correct protocol recognition and line-status reporting depend on it.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity: the sampled line state is produced at line 342, returned in the bus response at line 187 and used in byte and acknowledge processing at lines 412, 449, 474 and 477. Availability: corrupted sampled SDA can alter start and stop detection at lines 346 and 347 and thereby prevent the engine from advancing through a transaction.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could spoof the SDA input so the controller reports a false line state or misdetects protocol events and stalls or misroutes transfers.",
      "Enters Through": [
        "twd_sda_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        311
      ],
      "Held Lines": [
        342
      ],
      "Exit Lines": [
        187
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Interrupt-enable options",
      "Candidate Unit": "neorv32_twd",
      "Merged Into": "",
      "Why Not Kept": "These bus-written settings only tune an interrupt request output and are port options under the Port options rule, so they are not pieces of information of their own."
    },
    {
      "Candidate Name": "FIFO clear commands",
      "Candidate Unit": "neorv32_twd",
      "Merged Into": "",
      "Why Not Kept": "The clear commands only clear FIFO instances that buffer data between ports, so Port buffers bars them as independent information."
    },
    {
      "Candidate Name": "Serial clock and sampling-rate selection",
      "Candidate Unit": "neorv32_twd",
      "Merged Into": "",
      "Why Not Kept": "The serial clock lines and fsel use only shape serial sampling through smp.clk_en at line 329, which the Clocks and resets rule excludes."
    },
    {
      "Candidate Name": "FIFO occupancy and buffer handshake status",
      "Candidate Unit": "neorv32_twd",
      "Merged Into": "",
      "Why Not Kept": "The FIFO availability, free-space and read-transfer status only buffer or report data movement, so Port buffers and Buffer and engine status bits bar a separate concept."
    },
    {
      "Candidate Name": "Engine sequencing state, counter and busy status",
      "Candidate Unit": "neorv32_twd",
      "Merged Into": "",
      "Why Not Kept": "engine.state, engine.cnt and engine.busy only order or report protocol steps, so the Sequencing state rule bars them as information of their own."
    },
    {
      "Candidate Name": "Bus access command and response handshake",
      "Candidate Unit": "neorv32_twd",
      "Merged Into": "",
      "Why Not Kept": "The bus request address, direction, strobe and response acknowledge are access fields or handshake copies used to move accesses, so Access command fields, Forwarded transactions and Bus handshake copies provide no separate concept."
    },
    {
      "Candidate Name": "FIFO-held transmit data copy",
      "Candidate Unit": "neorv32_twd",
      "Merged Into": "C5",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "FIFO-held receive data copy",
      "Candidate Unit": "neorv32_twd",
      "Merged Into": "C6",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Protocol pacing and edge pulses",
      "Candidate Unit": "neorv32_twd",
      "Merged Into": "",
      "Why Not Kept": "The valid, rising-edge, falling-edge and related one-cycle pulses only pace or sequence transfers, so the Pacing pulses rule bars them as independent information."
    },
    {
      "Candidate Name": "FIFO build-time depths",
      "Candidate Unit": "neorv32_twd",
      "Merged Into": "",
      "Why Not Kept": "TWD_RX_FIFO and TWD_TX_FIFO only fix implementation size at build time and cannot be changed or withheld at run time."
    }
  ],
  "Notes": []
}
